    /**
     * Tests creating a new Catalog.
     *
     * @return    Catalog
     */
    public Catalog testCreate() throws Throwable {
    Catalog entity = null;

    LOGGER.info( "CatalogTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Catalog");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Catalog" );

    try {
        entity = service.createCatalog( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getCatalogId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Catalog with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

    /**
     * Tests reading a Catalog.
     *
     * @return    Catalog
     */
    public Catalog testRead() throws Throwable {
    LOGGER.info( "CatalogTest:testRead()" );
    LOGGER.info( "-- Reading a previously created Catalog" );

    Catalog entity = null;
    StringBuilder msg = new StringBuilder( "-- Failed to read Catalog with primary key" );
    msg.append( theId );

    try {
        entity = service.getCatalog( new CatalogFetchOneSummary(theId) );

        assertNotNull( entity,msg.toString() );

        // for use later
        theId = entity.getCatalogId();

        LOGGER.info( "-- Successfully found Catalog " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests updating a Catalog.
     *
     * @return    Catalog
     */
    public Catalog testUpdate() throws Throwable {
    LOGGER.info( "CatalogTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a Catalog." );

    StringBuilder msg = new StringBuilder( "Failed to update a Catalog : " );
    Catalog entity = null;

    try {
        UpdateCatalogCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setCatalogId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created Catalog." );

        entity = service.updateCatalog( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved Catalog - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests deleting a Catalog.
     */
    public void testDelete() throws Throwable {
    LOGGER.info( "CatalogTest:testDelete()" );
    LOGGER.info( "-- Deleting a previously created Catalog." );

    try {
        DeleteCatalogCommand deleteCommand = new DeleteCatalogCommand( theId );

        service.delete( deleteCommand );

        LOGGER.info( "-- Successfully deleted Catalog with primary key " + theId );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( "-- Failed to delete Catalog with primary key " + theId );

        throw e;
    }
}

    /**
     * Tests getting all Catalogs.
     *
     * @return    Collection
     */
    public List<Catalog> testGetAll() throws Throwable {
    LOGGER.info( "CatalogTest:testGetAll() - Retrieving Collection of Catalogs:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Catalog : " );
    List<Catalog> collection  = null;

    try {
        // call the static get method on the CatalogService
        collection = service.getAllCatalog();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Catalog currEntity  = null;
            Iterator<Catalog> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getCatalogId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

